function Status({ source, hasData = false, waiting=false }: { source?: SourceMeta; hasData?: boolean;waiting?:boolean }) { const simulated = source?.phase === 'simulation'; const active = hasData && source?.state === 'live' && source.phase === 'official'; return <span role="status" className={`status-chip ${simulated ? 'warning' : active ? 'active' : ''}`}><span className="status-dot"/>{waiting?'Aguardando configuração TSE':simulated ? 'Simulação do TSE' : source ? sourceLabels[source.state] : 'Conectando à fonte'}</span>; }
function Empty({ title = 'Aguardando dados oficiais', children, compact = false }: { title?: string; children?: ReactNode; compact?: boolean }) { return <div className={`empty-state ${compact ? 'compact' : ''}`}><div className="empty-icon"><Radio size={25}/></div><h3>{title}</h3><p>{children || 'Os resultados aparecerão aqui assim que a fonte do TSE disponibilizar a apuração para esta consulta.'}</p></div>; }
function Pagination({ count, page, onChange }: { count:number; page:number; onChange:(page:number)=>void }) { const pages = Math.ceil(count/25); if (!count) return null; return <div className="pagination"><span>{(page-1)*25+1}–{Math.min(page*25,count)} de {number(count)}</span><div><button className="button small" disabled={page===1} onClick={()=>onChange(page-1)}>Anterior</button><span>{page} / {pages}</span><button className="button small" disabled={page>=pages} onClick={()=>onChange(page+1)}>Próxima</button></div></div>; }
function TotalizationDetails({ summary, regional = false }: { summary?:Summary; regional?:boolean }) { const groups = [{name:'Seções eleitorais',items:[['Total',summary?.sectionsTotal],['Totalizadas',summary?.sectionsCounted],['Pendentes de totalização',summary?.sectionsPending],['Instaladas',summary?.sectionsInstalled],['Não instaladas',summary?.sectionsNotInstalled],['Apuradas',summary?.sectionsTallied],['Não apuradas',summary?.sectionsNotTallied]]},{name:'Eleitorado',items:[['Total',summary?.electorate],['Nas seções totalizadas',summary?.electorateCounted],['Nas seções instaladas',summary?.electorateInstalled],['Comparecimento',summary?.turnout],['Abstenção',summary?.abstention]]},{name:'Destinação dos votos',items:[['Total',summary?.votesTotal],['Computados a votáveis',summary?.votesComputed],['Válidos',summary?.votesValid],['Brancos',summary?.votesBlank],['Nulos',summary?.votesNull],['Nulos regulares',summary?.votesNullRegular],['Nulos técnicos',summary?.votesNullTechnical],['Anulados',summary?.votesAnnulled],['Anulados sub judice',summary?.votesSubJudice],['Sem candidato',summary?.votesWithoutCandidate]]}]; return <details className="card totalization-details"><summary><span><Vote size={17}/>Detalhes da totalização</span><ChevronDown size={16}/></summary><p>{regional?'Contadores somados dos arquivos estaduais do TSE. Percentuais usam a soma dos numeradores e denominadores; dados desconhecidos permanecem sem valor.':'Contadores reproduzidos da publicação oficial.'} Seções apuradas e totalizadas são campos distintos. Comparecimento e abstenção percentuais referem-se às seções instaladas.</p><div className="totalization-groups">{groups.map(group=><section key={group.name}><h3>{group.name}</h3><dl>{group.items.map(([label,value])=><div key={String(label)}><dt>{label}</dt><dd>{number(value as number | null | undefined)}</dd></div>)}</dl></section>)}</div>{summary?.officialStatus && <div className="totalization-status">Situação publicada: <strong>{summary.officialStatus}</strong></div>}</details>; }
function Metric({ label, value, detail, icon: Icon }: { label: string; value: string; detail: string; icon: typeof Vote }) { return <article className="metric card"><div className="metric-label">{label}<Icon size={17}/></div><strong>{value}</strong><span>{detail}</span></article>; }

